class Student:
    def __init__(self, name, marks):
        self.name = name
        self._marks = marks

    @property
    def marks(self):
        return self._marks

    @property
    def grade(self):
        return "Pass" if self._marks >= 40 else "Fail"

s = Student("Asha", 91)
print(s.marks)
print(s.grade)

class Student:
    def __init__(self, marks):
        self.marks = marks

    @property
    def marks(self):
        return self._marks

    @marks.setter
    def marks(self, value):
        if not 0 <= value <= 100:
            raise ValueError("marks must be 0 to 100")
        self._marks = value

s = Student(80)
s.marks = 95
print(s.marks)
try:
    s.marks = -5
except ValueError as e:
    print(e)
print(s.marks)

